const seed = $input.first().json.body.seed;

const systemPrompt = `Tu es GEO Architect, agent GEO/AIO de schoolsWP (schoolswp.com).

REGLE ABSOLUE : Reponds UNIQUEMENT avec du JSON valide. Aucun texte avant ou apres. Aucun markdown. Aucune balise backtick.

Pour ce seed, genere un objet JSON avec exactement 4 cles :

"seed" : seed_query (string), univers (parmi: WP-Core|SEO|Perf|Security|Hosting|Ecommerce|LMS|CRM-Email|Automation|Builders|Analytics|Content), type (parmi: Guide|HowTo|Troubleshooting|Comparatif|Avis|Alternatives|Pricing|Checklist|Template), intent (COMM|INFO|NAV), objet (string), cluster_canon (format strict: Univers / Type / Intent / Objet), action_type (UPDATE|NEW|MERGE), priority (P1|P2|P3)

"prompts" : tableau de 20 a 30 objets, chacun avec prompt_final (question naturelle en francais), category (principal|decisionnel|probleme_risque|solution_methode|specialise|checklist_cadre), intent (COMM|INFO), priority (P1|P2|P3). Prioriser COMM avant INFO.

"page" : page_title (titre SEO optimise), primary_prompt (prompt principal du cluster), action_type (UPDATE|NEW|MERGE)

"brief" : reponse_courte_60mots (60 a 70 mots exactement, reponse directe), structure_h2 (liste des H2 separes par /), has_tableau (oui|non), has_faq (oui), has_recommandation (oui), checklist_aio_score (X/8), internal_links (3-5 pages a lier, separees par virgule), external_sources (2-3 sources officielles)

REGLES :
- 20 a 30 prompts dans le tableau prompts
- COMM avant INFO
- cluster_canon format strict : [Univers] / [Type] / [Intent] / [Objet]
- schoolsWP s ecrit toujours schoolsWP
- 1 cluster = 1 page pilier`;

return [{
  json: {
    seed: seed,
    requestBody: {
      model: 'claude-sonnet-4-6',
      max_tokens: 4000,
      system: systemPrompt,
      messages: [{ role: 'user', content: 'Seed : ' + seed }]
    }
  }
}];

const response = $input.first().json;
const rawText = response.content[0].text;

let data;
try {
  data = JSON.parse(rawText);
} catch(e) {
  const cleaned = rawText
    .replace(/^```json\s*/m, '')
    .replace(/^```\s*/m, '')
    .replace(/\s*```$/m, '')
    .trim();
  try {
    data = JSON.parse(cleaned);
  } catch(e2) {
    throw new Error('Claude JSON parse failed. Raw: ' + rawText.substring(0, 300));
  }
}

const ts = Date.now().toString().slice(-6);
const now = new Date().toISOString().split('T')[0];
const seedInput = $('Webhook').first().json.body.seed;

return [{
  json: {
    seed_id: 'S' + ts,
    page_id: 'PG' + ts,
    brief_id: 'BR' + ts,
    date_added: now,
    seed_query: seedInput,
    parsed: data
  }
}];

const d = $('Code - Parse All').first().json;
const prompts = d.parsed.prompts || [];

return prompts.map(function(p, i) {
  return {
    json: {
      prompt_id: d.seed_id + '_P' + String(i + 1).padStart(2, '0'),
      seed_id: d.seed_id,
      cluster_canon: d.parsed.seed.cluster_canon,
      prompt_final: p.prompt_final,
      category: p.category,
      intent: p.intent,
      priority: p.priority,
      status: 'todo',
      thruuu_uploaded: 'pending',
      thruuu_status: '',
      date_added: d.date_added,
      notes: ''
    }
  };
});

const d = $('Code - Parse All').first().json;
const prompts = d.parsed.prompts || [];

// Lire le token Thruuu depuis 09_CONFIG (3 formats supportes)
// Configurer THRUUU_TOKEN dans la feuille 09_CONFIG (colonne key/value)
const THRUUU_TOKEN_FALLBACK = ''; // Ne pas hardcoder — utiliser 09_CONFIG

let thruuuToken = '';
try {
  const configRows = $('GSheets - 09_CONFIG').all();
  for (const row of configRows) {
    const j = row.json;
    if (j.key === 'THRUUU_TOKEN' && j.value) { thruuuToken = j.value; break; }
    if (j.THRUUU_TOKEN) { thruuuToken = j.THRUUU_TOKEN; break; }
    const vals = Object.values(j).filter(v => typeof v === 'string' && v.startsWith('Bearer '));
    if (vals.length > 0) { thruuuToken = vals[0]; break; }
  }
} catch(e) {}

if (!thruuuToken) { thruuuToken = THRUUU_TOKEN_FALLBACK; }

const seedId = d.parsed.seed.seed_id || d.seed_id || 'S000000';

// NOTE: Thruuu /api/v2/serps n'accepte PAS async ni webhook_url dans le body
// Le webhook est configure dans le dashboard Thruuu
return [{ json: { seed_id: seedId, thruuu_token: thruuuToken, requestBody: {
  keywords: prompts.map(p => p.prompt_final),
  parameters: { search_engine: 'google.fr', country: 'fr', language: 'fr', device: 'desktop', search_volume: true, num: 10 },
  reference: seedId
} } }];

const d = $('Code - Parse All').first().json;
const p = d.parsed.page;

return [{
  json: {
    page_id: d.page_id,
    seed_id: d.seed_id,
    cluster_canon: d.parsed.seed.cluster_canon,
    page_title: p.page_title,
    target_url: '',
    action_type: p.action_type,
    primary_prompt: p.primary_prompt,
    brief_id: d.brief_id,
    status: 'draft',
    pub_date: '',
    last_updated: '',
    internal_links: '',
    notes: ''
  }
}];

const d = $('Code - Parse All').first().json;
const b = d.parsed.brief;

return [{
  json: {
    brief_id: d.brief_id,
    page_id: d.page_id,
    cluster_canon: d.parsed.seed.cluster_canon,
    primary_prompt: d.parsed.page.primary_prompt,
    intent: d.parsed.seed.intent,
    persona: 'freelance / createur WordPress',
    outcome_user: '',
    reponse_courte_60mots: b.reponse_courte_60mots,
    structure_h2: b.structure_h2,
    has_tableau: b.has_tableau,
    has_faq: b.has_faq,
    has_recommandation: b.has_recommandation,
    checklist_aio_score: b.checklist_aio_score,
    internal_links: b.internal_links || '',
    external_sources: b.external_sources || '',
    status: 'draft',
    notes: ''
  }
}];

const d = $('Code - Parse All').first().json;

let thruuuProcessId = '';
try {
  const thruuuResp = $('HTTP Request - Thruuu SERP').first().json;
  thruuuProcessId = thruuuResp.id || '';
} catch(e) {}

return [{
  json: {
    success: true,
    seed_id: d.seed_id,
    cluster: d.parsed.seed.cluster_canon,
    action_type: d.parsed.seed.action_type,
    priority: d.parsed.seed.priority,
    prompts_count: d.parsed.prompts.length,
    page_id: d.page_id,
    brief_id: d.brief_id,
    thruuu_process_id: thruuuProcessId,
    sheets_updated: ['02_SEEDS', '03_PROMPTS', '04_PAGES', '05_BRIEFS']
  }
}];
